select * from #tmp_cli

SELECT * into #tmp_cli FROM (
SELECT 	Z.CCODCLIENTE, Z.CDESQUECARF 	
		/*
		Case when Z.CCODCLIENTE is null OR Z.CCODCLIENTE = ''  then 'NO REGISTRA'
		ELSE Z.CDESQUECARF END 		
		*/
FROM HYO00410.SOFCMACHYO_RIESGOS.dbo.[URIHHisCartera] Z (NOLOCK) 										
WHERE Z.CCODFECMES = '201503' AND Z.CCODCLIENTE --= @ccodcliente ) 	
		in (
/*
select top 1 * FROM HYO00410.SOFCMACHYO_RIESGOS.dbo.[URIHHisCartera] Z (NOLOCK) 										
WHERE CCODFECMES = '201503'	AND CCODCLIENTE --= @ccodcliente ) 	

SELECT * into #tmp_cli FROM  (select top 1 CCODCLIENTE,CDESQUECARF 
								from [URIHHisCartera] Z) as tmp
select * from #tmp_cli
--delete from #tmp_cli
--drop table #tmp_cli
insert into #tmp_cli
select 
*/
